/// <summary>
/// ApplicationInsights process log object
/// </summary>
public class OMGApplicationInsightsProcess extends OMGApplicationInsights
{
}

Method.Source:
/// <summary>
/// Return new instance of OMGApplicationInsightsProcess
/// </summary>
/// <param name = "_messageTypeId">MessageTypeId</param>
/// <returns>Instance</returns>
public static OMGApplicationInsightsProcess newMessageTypeId(str _messageTypeId)
{
    return new OMGApplicationInsightsProcess(_messageTypeId);
}

/// <summary>
/// Add Error count property to event telemetry
/// </summary>
/// <param name = "_errorCount">ErrorCount</param>
public void addErrorCountProperty(int64 _errorCount)
{
    SysApplicationInsightsProperty property = OMGApplicationInsightsMessageErrorCountProperty::newFromErrorCount(_errorCount);
    eventTelemetry.addProperty(property);
}

/// <summary>
/// Add Error message property to event telemetry
/// </summary>
/// <param name = "_errorMessage">ErrorMessage</param>
public void addErrorMessage(str _errorMessage)
{
    SysApplicationInsightsProperty property = OMGApplicationInsightsErrorMessageProperty::newFromErrorMessage(_errorMessage);
    eventTelemetry.addProperty(property);
}

/// <summary>
/// Add MessageId property to event telemetry
/// </summary>
/// <param name = "_messageId">MessageId</param>
public void addMessageId(str _messageId)
{
    SysApplicationInsightsProperty property = OMGApplicationInsightsMessageIdProperty::newFromMessageId(_messageId);
    eventTelemetry.addProperty(property);
}
